package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import java.sql.Timestamp;import java.security.MessageDigest;import java.util.function.Supplier;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.learning.githubevidence.v1.*;
final class GitHubEvidenceStore {
 record Evidence(UUID evidenceId,UUID roadmapId,UUID spaceId,UUID nodeId,String nodeTitle,String visibility,String state,long version,UUID repositoryId,UUID commitId,long commitVersion,String repositoryFullName,String sha,String subject,String authorLogin,String committedAt,String importedAt,String url,String memo,String createdAt,String updatedAt){}
 record Input(UUID nodeId,UUID repositoryId,UUID commitId,String memo){}
 record Recorded(Evidence evidence,boolean created){}
 record Page<T>(List<T> items,UUID nextAfter){}
 record Revision(UUID revisionId,UUID evidenceId,long version,UUID actorId,String occurredAt,Evidence snapshot){}
 record Related(UUID evidenceId,UUID roadmapId,String roadmapTitle,String roadmapState,UUID nodeId,String nodeTitle,String evidenceState,long evidenceVersion,UUID repositoryId,UUID commitId,String repositoryFullName,String sha){}
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final RoadmapStore roadmaps;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 GitHubEvidenceStore(DataSource ds,Clock clock,RoadmapStore roadmaps){jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);this.roadmaps=roadmaps;}
 static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"GitHub evidence unavailable");}
 static void trace(String t){if(t==null||!t.matches("[0-9a-f]{32}")||t.equals("0".repeat(32)))throw LearningStudyStore.bad();}
 static void memo(String m){RoadmapGraph.text("Evidence",m,8192);}
 static void active(RoadmapStore.Roadmap root){if(!root.state().equals("ACTIVE"))throw missing();}
 Evidence get(UUID space,UUID roadmap,UUID id){RoadmapGraph.id(space);RoadmapGraph.id(roadmap);RoadmapGraph.id(id);var rows=jdbc.query("SELECT v.snapshot::text FROM roadmap r JOIN learning_evidence e ON e.roadmap_id=r.roadmap_id JOIN learning_evidence_revision v ON v.evidence_id=e.evidence_id AND v.version=e.version WHERE r.space_id=? AND r.roadmap_id=? AND e.evidence_id=? AND e.kind='GITHUB'",(rs,n)->json.readValue(rs.getString(1),Evidence.class),space,roadmap,id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 Recorded record(UUID space,UUID roadmap,UUID actor,String key,Input input,String trace,Supplier<GitHubReferenceClient.Reference> owner){RoadmapGraph.id(actor);trace(trace);if(input==null||key==null||!key.matches("[0-9a-f]{32}"))throw LearningStudyStore.bad();RoadmapGraph.id(input.nodeId());RoadmapGraph.id(input.repositoryId());RoadmapGraph.id(input.commitId());memo(input.memo());String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(input)));}catch(Exception e){throw new IllegalStateException(e);}
  return tx.execute(s->{var root=roadmaps.lock(space,roadmap);var prior=jdbc.query("SELECT evidence_id,request_fingerprint,kind FROM learning_evidence WHERE roadmap_id=? AND request_key=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class),rs.getString(2)+":"+rs.getString(3)),roadmap,key);if(!prior.isEmpty()){var old=prior.getFirst();if(!old.getValue().equals(hash+":GITHUB"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Request intent changed");return new Recorded(get(space,roadmap,old.getKey()),false);}active(root);var titles=jdbc.queryForList("SELECT title FROM roadmap_node WHERE roadmap_id=? AND node_id=? AND state='ACTIVE'",String.class,roadmap,input.nodeId());if(titles.isEmpty())throw missing();if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM learning_evidence WHERE roadmap_id=? AND node_id=? AND kind='GITHUB' AND github_repository_id=? AND github_commit_id=? AND state='ACTIVE')",Boolean.class,roadmap,input.nodeId(),input.repositoryId(),input.commitId())))throw new ResponseStatusException(HttpStatus.CONFLICT,"Commit already linked to this node");var ref=owner.get();GitHubReferenceClient.validate(ref,space,input.repositoryId(),input.commitId(),actor);var now=clock.instant();var e=new Evidence(ids.next(),roadmap,space,input.nodeId(),titles.getFirst(),"PRIVATE","ACTIVE",1,ref.repositoryId(),ref.commitId(),1,ref.repositoryFullName(),ref.sha(),ref.subject(),ref.authorLogin(),ref.committedAt(),ref.importedAt(),ref.url(),input.memo(),now.toString(),now.toString());jdbc.update("INSERT INTO learning_evidence(evidence_id,roadmap_id,node_id,state,version,kind,github_repository_id,github_commit_id,request_key,request_fingerprint) VALUES (?,?,?,'ACTIVE',1,'GITHUB',?,?,?,?)",e.evidenceId(),roadmap,input.nodeId(),input.repositoryId(),input.commitId(),key,hash);revision(e,actor,trace,"GitHubLearningEvidenceLinked",now);return new Recorded(e,true);});
 }
 Evidence change(UUID space,UUID roadmap,UUID id,UUID actor,long expected,String memo,boolean retire,String trace){RoadmapGraph.id(actor);trace(trace);if(expected<1)throw LearningStudyStore.bad();if(!retire)memo(memo);return tx.execute(s->{active(roadmaps.lock(space,roadmap));var old=get(space,roadmap,id);if(old.version()!=expected)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Evidence changed; inspect latest");if(!old.state().equals("ACTIVE"))throw missing();if(!retire&&old.memo().equals(memo))return old;var now=clock.instant();var e=new Evidence(id,roadmap,space,old.nodeId(),old.nodeTitle(),"PRIVATE",retire?"RETIRED":"ACTIVE",Math.addExact(old.version(),1),old.repositoryId(),old.commitId(),1,old.repositoryFullName(),old.sha(),old.subject(),old.authorLogin(),old.committedAt(),old.importedAt(),old.url(),retire?old.memo():memo,old.createdAt(),now.toString());jdbc.update("UPDATE learning_evidence SET state=?,version=? WHERE evidence_id=?",e.state(),e.version(),id);revision(e,actor,trace,retire?"GitHubLearningEvidenceRetired":"GitHubLearningEvidenceUpdated",now);return e;});}
 Page<Evidence> page(UUID space,UUID roadmap,String state,UUID after,int limit){roadmaps.inspect(space,roadmap);bounds(state,after,limit);var args=new ArrayList<Object>(List.of(space,roadmap,state));if(after!=null)args.add(after);args.add(limit+1);var rows=jdbc.query("SELECT v.snapshot::text FROM roadmap r JOIN learning_evidence e ON e.roadmap_id=r.roadmap_id JOIN learning_evidence_revision v ON v.evidence_id=e.evidence_id AND v.version=e.version WHERE r.space_id=? AND r.roadmap_id=? AND e.kind='GITHUB' AND e.state=?"+(after==null?"":" AND e.evidence_id>?")+" ORDER BY e.evidence_id LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Evidence.class),args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page<>(items,rows.size()>limit?items.getLast().evidenceId():null);}
 Page<Related> related(UUID space,UUID repo,UUID commit,String state,UUID after,int limit){RoadmapGraph.id(space);RoadmapGraph.id(repo);RoadmapGraph.id(commit);bounds(state,after,limit);var args=new ArrayList<Object>(List.of(space,repo,commit,state));if(after!=null)args.add(after);args.add(limit+1);var rows=jdbc.query("SELECT r.title,r.state,v.snapshot::text FROM roadmap r JOIN learning_evidence e ON e.roadmap_id=r.roadmap_id JOIN learning_evidence_revision v ON v.evidence_id=e.evidence_id AND v.version=e.version WHERE r.space_id=? AND e.kind='GITHUB' AND e.github_repository_id=? AND e.github_commit_id=? AND e.state=?"+(after==null?"":" AND e.evidence_id>?")+" ORDER BY e.evidence_id LIMIT ?",(rs,n)->{var e=json.readValue(rs.getString(3),Evidence.class);return new Related(e.evidenceId(),e.roadmapId(),rs.getString(1),rs.getString(2),e.nodeId(),e.nodeTitle(),e.state(),e.version(),repo,commit,e.repositoryFullName(),e.sha());},args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page<>(items,rows.size()>limit?items.getLast().evidenceId():null);}
 static void bounds(String state,UUID after,int limit){if(!Set.of("ACTIVE","RETIRED").contains(state)||limit<1||limit>100)throw LearningStudyStore.bad();if(after!=null)RoadmapGraph.id(after);}
 List<Revision> history(UUID space,UUID roadmap,UUID id,long before,int limit){get(space,roadmap,id);if(before<1||limit<1||limit>10)throw LearningStudyStore.bad();return jdbc.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM learning_evidence_revision WHERE evidence_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),id,rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Evidence.class)),id,before,limit);}
 private void revision(Evidence e,UUID actor,String trace,String type,Instant now){UUID revision=ids.next();jdbc.update("INSERT INTO learning_evidence_revision VALUES (?,?,?,?,?,?::jsonb)",revision,e.evidenceId(),e.version(),actor,Timestamp.from(now),json.writeValueAsString(e));var p=GitHubEvidenceChangedPayloadV1.newBuilder().setEvidenceId(e.evidenceId().toString()).setRevisionId(revision.toString()).setRoadmapId(e.roadmapId().toString()).setNodeId(e.nodeId().toString()).setNodeTitle(e.nodeTitle()).setVisibility("PRIVATE").setState(e.state()).setVersion(e.version()).setRepositoryId(e.repositoryId().toString()).setCommitId(e.commitId().toString()).setCommitVersion(1).setRepositoryFullName(e.repositoryFullName()).setSha(e.sha()).setSubject(e.subject()).setAuthorLogin(e.authorLogin()==null?"":e.authorLogin()).setCommittedAt(e.committedAt()).setImportedAt(e.importedAt()).setUrl(e.url()).setMemo(e.memo()).setCreatedAt(e.createdAt()).setUpdatedAt(e.updatedAt()).build();GitHubEvidenceEvents.write(jdbc,ids,e.spaceId(),e.evidenceId(),actor,trace,now,"github-evidence","github-evidence-events","GitHubLearningEvidence",type,p.toByteArray());}
}
